// GENERADO por scripts/gen-migrations.mjs — NO editar a mano.
// SQL de las migraciones embebido para correrlas desde /api/admin/migrate en Vercel.
export const MIGRATIONS: { name: string; sql: string }[] = [
  { name: "0000_init", sql: "-- F1 Fundaciones — backbone de tenancy + config + outbox, con AISLAMIENTO POR RLS (D4).\n-- El aislamiento no depende de que el código recuerde el WHERE: Postgres niega las filas\n-- de otros tenants aunque la query lo olvide. `app.tenant_id` lo setea withTenant() por\n-- transacción; FORCE ROW LEVEL SECURITY hace que la política aplique INCLUSO al owner.\n\n-- gen_random_uuid() es core desde Postgres 13 (Neon corre PG16); no requiere pgcrypto.\n\n-- Registro de tenants (NO scopeado por tenant: es el índice de la plataforma).\ncreate table if not exists tenants (\n  id         uuid primary key default gen_random_uuid(),\n  slug       text unique not null,\n  name       text not null,\n  status     text not null default 'active',\n  created_at timestamptz not null default now()\n);\n\n-- Regiones (ciudades). Ciudad = región dentro del tenant (D1).\ncreate table if not exists regions (\n  id         uuid primary key default gen_random_uuid(),\n  tenant_id  uuid not null references tenants(id),\n  slug       text not null,\n  name       text not null,\n  created_at timestamptz not null default now(),\n  unique (tenant_id, slug)\n);\n\n-- Comercios (commerce). En V1: el Pet Shop propio, modelado como commerce independiente.\ncreate table if not exists merchants (\n  id         uuid primary key default gen_random_uuid(),\n  tenant_id  uuid not null references tenants(id),\n  region_id  uuid references regions(id),\n  slug       text not null,\n  name       text not null,\n  created_at timestamptz not null default now(),\n  unique (tenant_id, slug)\n);\n\n-- Config values (gestionados por la plataforma; filtrados por scope en la capa de\n-- servicio, no por RLS de tenant, porque los de scope 'platform' son globales).\ncreate table if not exists config_values (\n  id             uuid primary key default gen_random_uuid(),\n  key            text not null,\n  scope_type     text not null check (scope_type in ('platform','tenant','region','merchant','user')),\n  scope_id       text not null,\n  value          jsonb not null,\n  version        int  not null default 1,\n  effective_from timestamptz not null default now(),\n  actor          text not null,\n  reason         text,\n  created_at     timestamptz not null default now()\n);\ncreate index if not exists config_values_lookup on config_values (key, scope_type, scope_id);\n\n-- Outbox transaccional: el evento se escribe en la misma tx que el cambio de estado.\n-- Es una tabla de INFRAESTRUCTURA drenada por un proceso de plataforma (cross-tenant),\n-- por eso NO va bajo RLS de tenant (si lo estuviera, el drenaje no vería nada). El\n-- `tenant_id` correcto lo garantiza la capa de app: enqueueEvent() se llama dentro de\n-- withTenant() y toma el tenantId del contexto. Ningún código tenant-facing hace SELECT\n-- sobre esta tabla.\ncreate table if not exists outbox_events (\n  id           uuid primary key default gen_random_uuid(),\n  tenant_id    uuid not null,\n  type         text not null,\n  version      int  not null default 1,\n  payload      jsonb not null,\n  status       text not null default 'pending' check (status in ('pending','published')),\n  occurred_at  timestamptz not null default now(),\n  published_at timestamptz\n);\ncreate index if not exists outbox_pending on outbox_events (status, occurred_at);\n\n-- Rol de aplicación: la app NO debe conectarse como superusuario (los superusuarios\n-- BYPASSean RLS). Conecta como `commerce_app`, que al no ser owner de las tablas queda\n-- siempre sujeto a las políticas. En Neon: crear el rol de la app y darle estos grants.\ndo $$ begin\n  begin\n    if not exists (select from pg_roles where rolname = 'commerce_app') then\n      create role commerce_app;\n    end if;\n    grant usage on schema public to commerce_app;\n    grant select, insert, update, delete on all tables in schema public to commerce_app;\n    alter default privileges in schema public grant select, insert, update, delete on tables to commerce_app;\n  exception when insufficient_privilege then\n    -- En Neon el rol de la app es el OWNER (no superusuario), así que FORCE ROW LEVEL\n    -- SECURITY ya lo constriñe y no hace falta commerce_app. Si no hay privilegio para\n    -- crearlo, seguimos: el aislamiento igual aplica.\n    raise notice 'commerce_app no creado (sin privilegio); el rol owner + FORCE RLS alcanza';\n  end;\nend $$;\n\n-- Helper: tenant actual desde la variable de sesión. NULL si no está seteada → deniega\n-- todo (falla cerrado).\ncreate or replace function current_tenant_id() returns uuid\n  language sql stable\n  as $$ select nullif(current_setting('app.tenant_id', true), '')::uuid $$;\n\n-- Activar RLS en las tablas scopeadas por tenant.\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['regions','merchants'] loop\n    execute format('alter table %I enable row level security', t);\n    execute format('alter table %I force row level security', t);\n    if not exists (select from pg_policies where schemaname = 'public' and tablename = t and policyname = 'tenant_isolation') then\n      execute format(\n        'create policy tenant_isolation on %I using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())',\n        t\n      );\n    end if;\n  end loop;\nend $$;\n" },
  { name: "0001_catalog_inventory", sql: "-- F2 — Catálogo e Inventario. Tablas propias de estos módulos (cada módulo dueño de sus\n-- tablas — [A1]). Todas scopeadas por tenant y bajo RLS. Los montos son bigint en\n-- centavos (D7). Depende de 0000_init.sql (tenants/regions/merchants + rol commerce_app).\n\ncreate table if not exists products (\n  id          uuid primary key default gen_random_uuid(),\n  tenant_id   uuid not null,\n  merchant_id uuid not null references merchants(id),\n  slug        text not null,\n  name        text not null,\n  description text,\n  status      text not null default 'active' check (status in ('active','inactive')),\n  created_at  timestamptz not null default now(),\n  unique (merchant_id, slug)\n);\n\ncreate table if not exists variants (\n  id         uuid primary key default gen_random_uuid(),\n  tenant_id  uuid not null,\n  product_id uuid not null references products(id),\n  sku        text not null,\n  name       text not null,\n  created_at timestamptz not null default now(),\n  unique (product_id, sku)\n);\n\ncreate table if not exists prices (\n  id             uuid primary key default gen_random_uuid(),\n  tenant_id      uuid not null,\n  variant_id     uuid not null references variants(id),\n  amount_minor   bigint not null check (amount_minor >= 0),\n  currency       char(3) not null default 'ARS',\n  effective_from timestamptz not null default now()\n);\ncreate index if not exists prices_lookup on prices (variant_id, effective_from desc);\n\n-- Inventario: available = disponible para vender, reserved = retenido por reservas 'held'.\ncreate table if not exists inventory (\n  variant_id uuid primary key references variants(id),\n  tenant_id  uuid not null,\n  available  int not null default 0 check (available >= 0),\n  reserved   int not null default 0 check (reserved >= 0),\n  updated_at timestamptz not null default now()\n);\n\n-- Reservas de stock con TTL (evita oversell — [G1]). held → confirmed (venta) | released.\ncreate table if not exists stock_reservations (\n  id         uuid primary key default gen_random_uuid(),\n  tenant_id  uuid not null,\n  order_id   uuid,\n  variant_id uuid not null references variants(id),\n  qty        int not null check (qty > 0),\n  status     text not null default 'held' check (status in ('held','confirmed','released')),\n  expires_at timestamptz not null,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists stock_res_expiry on stock_reservations (status, expires_at);\n\n-- RLS en todas las tablas de dominio (scopeadas por tenant).\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['products','variants','prices','inventory','stock_reservations'] loop\n    execute format('alter table %I enable row level security', t);\n    execute format('alter table %I force row level security', t);\n    if not exists (select from pg_policies where schemaname = 'public' and tablename = t and policyname = 'tenant_isolation') then\n      execute format(\n        'create policy tenant_isolation on %I using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())',\n        t\n      );\n    end if;\n  end loop;\nend $$;\n\n-- Libera reservas vencidas y devuelve el stock. SECURITY DEFINER: la corre el cron como\n-- tarea de plataforma (cross-tenant), por eso bypassea RLS a propósito. Devuelve cuántas\n-- reservas liberó.\ncreate or replace function release_expired_reservations() returns int\n  language plpgsql security definer as $$\ndeclare n int;\nbegin\n  with expired as (\n    update stock_reservations set status = 'released'\n     where status = 'held' and expires_at < now()\n     returning variant_id, qty\n  ), agg as (\n    select variant_id, sum(qty)::int as q from expired group by variant_id\n  )\n  update inventory i\n     set available = i.available + a.q, reserved = i.reserved - a.q, updated_at = now()\n    from agg a\n   where i.variant_id = a.variant_id;\n  get diagnostics n = row_count;\n  return coalesce(n, 0);\nend $$;\n" },
  { name: "0002_orders", sql: "-- F3 — Órdenes. Esqueleto a prueba de multi-seller SIN rehacer Order ([E1]):\n--   order (1 checkout del cliente) → seller_order (la parte de UN comercio) → order_item\n--   Los items cuelgan de seller_order, NO de order → multi-seller = N seller_orders.\n--   V1: 1 seller_order por order, forzado por config (orders.maxSellersPerOrder), no acá.\n-- Montos en centavos (D7). Todo bajo RLS por tenant.\n\ncreate table if not exists orders (\n  id          uuid primary key default gen_random_uuid(),\n  tenant_id   uuid not null,\n  customer_id uuid,\n  status      text not null default 'pending_payment'\n              check (status in ('pending_payment','confirmed','completed','cancelled','refunded','partially_refunded')),\n  currency    char(3) not null default 'ARS',\n  total_minor bigint not null default 0 check (total_minor >= 0),\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now()\n);\n\ncreate table if not exists seller_orders (\n  id             uuid primary key default gen_random_uuid(),\n  tenant_id      uuid not null,\n  order_id       uuid not null references orders(id),\n  merchant_id    uuid not null references merchants(id),\n  status         text not null default 'pending'\n                 check (status in ('pending','preparing','ready','in_transit','delivered','rejected','delivery_failed','cancelled')),\n  subtotal_minor bigint not null default 0 check (subtotal_minor >= 0),\n  created_at     timestamptz not null default now()\n);\ncreate index if not exists seller_orders_by_order on seller_orders (order_id);\n\ncreate table if not exists order_items (\n  id               uuid primary key default gen_random_uuid(),\n  tenant_id        uuid not null,\n  seller_order_id  uuid not null references seller_orders(id),\n  variant_id       uuid not null references variants(id),\n  qty              int not null check (qty > 0),\n  unit_price_minor bigint not null check (unit_price_minor >= 0),\n  reservation_id   uuid,\n  created_at       timestamptz not null default now()\n);\ncreate index if not exists order_items_by_seller_order on order_items (seller_order_id);\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['orders','seller_orders','order_items'] loop\n    execute format('alter table %I enable row level security', t);\n    execute format('alter table %I force row level security', t);\n    if not exists (select from pg_policies where schemaname = 'public' and tablename = t and policyname = 'tenant_isolation') then\n      execute format(\n        'create policy tenant_isolation on %I using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())',\n        t\n      );\n    end if;\n  end loop;\nend $$;\n" },
  { name: "0003_payments", sql: "-- F3 (parte 2) — Payments + LEDGER de doble partida (fuente de verdad del dinero).\n-- payment (1 por order) → payment_allocation (reparto: merchant/comisión/delivery/…).\n-- ledger_entries: doble partida; cada asiento balancea (sum debit = sum credit).\n-- refunds: reversos; un refund parcial afecta UNA allocation sin tocar las demás (#9).\n-- processed_webhooks: idempotencia de webhooks (dedup por provider_event_id).\n-- Montos en centavos (D7). Todo bajo RLS por tenant.\n\ncreate table if not exists payments (\n  id           uuid primary key default gen_random_uuid(),\n  tenant_id    uuid not null,\n  order_id     uuid not null references orders(id),\n  provider     text not null,\n  provider_ref text,\n  status       text not null default 'pending' check (status in ('pending','captured','failed','refunded','partially_refunded')),\n  amount_minor bigint not null check (amount_minor >= 0),\n  currency     char(3) not null default 'ARS',\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\ncreate index if not exists payments_by_order on payments (order_id);\n\ncreate table if not exists payment_allocations (\n  id              uuid primary key default gen_random_uuid(),\n  tenant_id       uuid not null,\n  payment_id      uuid not null references payments(id),\n  seller_order_id uuid references seller_orders(id),\n  target_type     text not null check (target_type in ('merchant','platform_commission','delivery','psp_fee','promo_subsidy')),\n  target_ref      text,\n  amount_minor    bigint not null check (amount_minor >= 0),\n  refunded_minor  bigint not null default 0 check (refunded_minor >= 0),\n  created_at      timestamptz not null default now()\n);\ncreate index if not exists allocations_by_payment on payment_allocations (payment_id);\n\ncreate table if not exists ledger_entries (\n  id           uuid primary key default gen_random_uuid(),\n  tenant_id    uuid not null,\n  payment_id   uuid references payments(id),\n  account      text not null,\n  account_ref  text,\n  debit_minor  bigint not null default 0 check (debit_minor >= 0),\n  credit_minor bigint not null default 0 check (credit_minor >= 0),\n  memo         text,\n  created_at   timestamptz not null default now()\n);\ncreate index if not exists ledger_by_account on ledger_entries (account, account_ref);\n\ncreate table if not exists refunds (\n  id            uuid primary key default gen_random_uuid(),\n  tenant_id     uuid not null,\n  payment_id    uuid not null references payments(id),\n  allocation_id uuid references payment_allocations(id),\n  amount_minor  bigint not null check (amount_minor > 0),\n  reason        text,\n  created_at    timestamptz not null default now()\n);\n\ncreate table if not exists processed_webhooks (\n  provider_event_id text primary key,\n  tenant_id         uuid not null,\n  payment_id        uuid,\n  processed_at      timestamptz not null default now()\n);\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['payments','payment_allocations','ledger_entries','refunds','processed_webhooks'] loop\n    execute format('alter table %I enable row level security', t);\n    execute format('alter table %I force row level security', t);\n    if not exists (select from pg_policies where schemaname = 'public' and tablename = t and policyname = 'tenant_isolation') then\n      execute format(\n        'create policy tenant_isolation on %I using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())',\n        t\n      );\n    end if;\n  end loop;\nend $$;\n" },
  { name: "0004_delivery", sql: "-- F4 — Delivery. Guarda origen/destino/costo/cadete/eventos (sección 7 del doc). El\n-- modelo YA soporta consolidación futura (V4): `routes` agrupa varias `deliveries` con\n-- múltiples pickups, sin rehacer nada. V1: 1 seller_order → 1 delivery, sin route.\n-- Montos en centavos (D7). Todo bajo RLS por tenant.\n\ncreate table if not exists drivers (\n  id         uuid primary key default gen_random_uuid(),\n  tenant_id  uuid not null,\n  name       text not null,\n  phone      text,\n  active     boolean not null default true,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists delivery_zones (\n  id         uuid primary key default gen_random_uuid(),\n  tenant_id  uuid not null,\n  region_id  uuid references regions(id),\n  name       text not null,\n  created_at timestamptz not null default now()\n);\n\n-- Tarifa por zona: costo del cadete + lo que paga el cliente + quién financia el gap.\ncreate table if not exists delivery_rates (\n  id                    uuid primary key default gen_random_uuid(),\n  tenant_id             uuid not null,\n  zone_id               uuid not null references delivery_zones(id),\n  cadete_cost_minor     bigint not null check (cadete_cost_minor >= 0),\n  customer_charge_minor bigint not null check (customer_charge_minor >= 0),\n  subsidy_source        text not null default 'platform' check (subsidy_source in ('platform','merchant','promo','none')),\n  created_at            timestamptz not null default now()\n);\n\n-- Route: agrupa entregas (consolidación V4). Presente desde ya, sin usar en V1.\ncreate table if not exists routes (\n  id         uuid primary key default gen_random_uuid(),\n  tenant_id  uuid not null,\n  driver_id  uuid references drivers(id),\n  status     text not null default 'planned' check (status in ('planned','in_progress','completed')),\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists deliveries (\n  id                    uuid primary key default gen_random_uuid(),\n  tenant_id             uuid not null,\n  seller_order_id       uuid not null references seller_orders(id),\n  route_id              uuid references routes(id),\n  driver_id             uuid references drivers(id),\n  zone_id               uuid references delivery_zones(id),\n  status                text not null default 'pending'\n                        check (status in ('pending','assigned','picked_up','in_transit','delivered','failed')),\n  cadete_cost_minor     bigint not null default 0 check (cadete_cost_minor >= 0),\n  customer_charge_minor bigint not null default 0 check (customer_charge_minor >= 0),\n  subsidy_source        text not null default 'platform',\n  eta_minutes           int,\n  created_at            timestamptz not null default now(),\n  updated_at            timestamptz not null default now()\n);\ncreate index if not exists deliveries_by_seller_order on deliveries (seller_order_id);\n\ncreate table if not exists delivery_events (\n  id          uuid primary key default gen_random_uuid(),\n  tenant_id   uuid not null,\n  delivery_id uuid not null references deliveries(id),\n  type        text not null,\n  data        jsonb,\n  created_at  timestamptz not null default now()\n);\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['drivers','delivery_zones','delivery_rates','routes','deliveries','delivery_events'] loop\n    execute format('alter table %I enable row level security', t);\n    execute format('alter table %I force row level security', t);\n    if not exists (select from pg_policies where schemaname = 'public' and tablename = t and policyname = 'tenant_isolation') then\n      execute format(\n        'create policy tenant_isolation on %I using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())',\n        t\n      );\n    end if;\n  end loop;\nend $$;\n" },
  { name: "0005_auth", sql: "-- Auth (Grupo A). Usuarios y roles scopeados por tenant, bajo RLS. El hash de password\n-- se guarda como texto (scrypt); nunca la contraseña en claro. Depende de 0000_init.\n\ncreate table if not exists users (\n  id            uuid primary key default gen_random_uuid(),\n  tenant_id     uuid not null,\n  email         text not null,\n  password_hash text not null,\n  created_at    timestamptz not null default now(),\n  unique (tenant_id, email)\n);\n\ncreate table if not exists user_roles (\n  id         uuid primary key default gen_random_uuid(),\n  tenant_id  uuid not null,\n  user_id    uuid not null references users(id),\n  role       text not null,\n  scope_type text not null check (scope_type in ('tenant','region','merchant')),\n  scope_id   text not null,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists user_roles_by_user on user_roles (user_id);\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['users','user_roles'] loop\n    execute format('alter table %I enable row level security', t);\n    execute format('alter table %I force row level security', t);\n    if not exists (select from pg_policies where schemaname = 'public' and tablename = t and policyname = 'tenant_isolation') then\n      execute format(\n        'create policy tenant_isolation on %I using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())',\n        t\n      );\n    end if;\n  end loop;\nend $$;\n" },
  { name: "0006_customer", sql: "-- Checkout completo (Grupo A). Libreta de direcciones del cliente, bajo RLS por tenant.\ncreate table if not exists addresses (\n  id          uuid primary key default gen_random_uuid(),\n  tenant_id   uuid not null,\n  customer_id uuid not null,\n  label       text,\n  street      text not null,\n  city        text,\n  zone        text,\n  notes       text,\n  created_at  timestamptz not null default now()\n);\ncreate index if not exists addresses_by_customer on addresses (customer_id);\n\ndo $$\nbegin\n  execute 'alter table addresses enable row level security';\n  execute 'alter table addresses force row level security';\n  if not exists (select from pg_policies where schemaname = 'public' and tablename = 'addresses' and policyname = 'tenant_isolation') then\n    execute 'create policy tenant_isolation on addresses using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())';\n  end if;\nend $$;\n" },
  { name: "0007_orders_checkout", sql: "-- Checkout completo: el pedido guarda la dirección de envío (snapshot), la ventana de\n-- entrega elegida y el costo de delivery cobrado. Snapshot en jsonb para preservar la\n-- dirección aunque el cliente la edite después.\nalter table orders add column if not exists shipping_address jsonb;\nalter table orders add column if not exists delivery_window text;\nalter table orders add column if not exists delivery_charge_minor bigint not null default 0;\n" },
  { name: "0008_product_images", sql: "-- Fotos de producto. Agrega image_url a products (URL http/https saneada en la capa de\n-- app). Idempotente: add column if not exists. La imagen es a nivel producto (todas las\n-- variantes comparten la foto principal en V1); si más adelante se quiere foto por\n-- variante, se agrega variants.image_url sin romper esto.\n\nalter table products add column if not exists image_url text;\n" },
  { name: "0009_categories", sql: "-- Categorías de producto (Perros, Gatos, Accesorios, Higiene, …). Por comercio, bajo RLS.\n-- Un producto pertenece a 0 o 1 categoría (V1). Idempotente. `position` ordena las\n-- categorías en la vitrina; `image_url` es la foto de la ficha de categoría (saneada en app).\n\ncreate table if not exists categories (\n  id          uuid primary key default gen_random_uuid(),\n  tenant_id   uuid not null,\n  merchant_id uuid not null references merchants(id),\n  slug        text not null,\n  name        text not null,\n  image_url   text,\n  position    int not null default 0,\n  created_at  timestamptz not null default now(),\n  unique (merchant_id, slug)\n);\ncreate index if not exists categories_by_merchant on categories (merchant_id, position);\n\n-- Un producto puede estar en una categoría (nullable: productos sin categoría siguen válidos).\nalter table products add column if not exists category_id uuid references categories(id);\n\ndo $$\nbegin\n  execute 'alter table categories enable row level security';\n  execute 'alter table categories force row level security';\n  if not exists (select from pg_policies where schemaname = 'public' and tablename = 'categories' and policyname = 'tenant_isolation') then\n    execute 'create policy tenant_isolation on categories using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())';\n  end if;\nend $$;\n" },
  { name: "0010_adoptions", sql: "-- Adopciones / callejeritos: publicaciones de mascotas en adopción del comercio (o de la\n-- comunidad). Tabla propia del módulo, por tenant y bajo RLS. Idempotente.\n-- status: 'available' (se muestra en la tienda) | 'adopted' (dado en adopción, oculto).\n\ncreate table if not exists adoptions (\n  id                uuid primary key default gen_random_uuid(),\n  tenant_id         uuid not null,\n  name              text not null,\n  species           text not null default 'otro' check (species in ('perro','gato','otro')),\n  age               text,\n  description       text,\n  image_url         text,\n  contact_whatsapp  text,\n  status            text not null default 'available' check (status in ('available','adopted')),\n  created_at        timestamptz not null default now()\n);\ncreate index if not exists adoptions_by_status on adoptions (status, created_at desc);\n\ndo $$\nbegin\n  execute 'alter table adoptions enable row level security';\n  execute 'alter table adoptions force row level security';\n  if not exists (select from pg_policies where schemaname = 'public' and tablename = 'adoptions' and policyname = 'tenant_isolation') then\n    execute 'create policy tenant_isolation on adoptions using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())';\n  end if;\nend $$;\n" },
  { name: "0011_food_nutrition", sql: "-- Datos nutricionales del alimento (para la calculadora de consumo y reposición).\n-- kcal_per_kg y protein_pct van a nivel producto; net_weight_kg (peso neto de la bolsa)\n-- a nivel variante (cada talle es una presentación con su peso). Todo nullable: un producto\n-- que NO es alimento simplemente los deja en null. Idempotente.\n\nalter table products add column if not exists kcal_per_kg  int;\nalter table products add column if not exists protein_pct  numeric(4,1);\nalter table variants add column if not exists net_weight_kg numeric(7,3);\n" },
  { name: "0012_pets", sql: "-- Perfiles de mascota del cliente (\"los animales de la casa\"). Base de la calculadora de\n-- consumo y de los avisos de reposición. Por tenant y bajo RLS. Idempotente.\n-- activity: etapa/actividad (cachorro, adulto_bajo, adulto_normal, adulto_activo, senior).\n\ncreate table if not exists pets (\n  id          uuid primary key default gen_random_uuid(),\n  tenant_id   uuid not null,\n  customer_id uuid not null,\n  name        text not null,\n  species     text not null default 'perro' check (species in ('perro','gato','otro')),\n  breed       text,\n  weight_kg   numeric(6,2),\n  activity    text not null default 'adulto_normal',\n  created_at  timestamptz not null default now()\n);\ncreate index if not exists pets_by_customer on pets (customer_id, created_at desc);\n\ndo $$\nbegin\n  execute 'alter table pets enable row level security';\n  execute 'alter table pets force row level security';\n  if not exists (select from pg_policies where schemaname = 'public' and tablename = 'pets' and policyname = 'tenant_isolation') then\n    execute 'create policy tenant_isolation on pets using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())';\n  end if;\nend $$;\n" },
  { name: "0013_customers_channel", sql: "-- Eslabón 1 — Operatoria de venta. La MASCOTA es el centro: el cliente se identifica por\n-- TELÉFONO (ficha reutilizable, sin obligar a registrarse) y el pedido guarda para quién es\n-- (mascota), cómo se paga y por qué canal entró. Base del flywheel (recompra/reposición).\n--\n-- Solo DDL: en Neon la app corre como owner con FORCE RLS, así que durante la migración\n-- current_tenant_id() es NULL y un backfill de datos (INSERT/UPDATE con policy) tocaría 0\n-- filas. El backfill (ficha de cliente por usuario, estado de pago de pedidos ya pagados) se\n-- hace en código, con contexto de tenant. Idempotente.\n\n-- Ficha de cliente por tenant. El teléfono normalizado (solo dígitos) es la llave práctica.\n-- Para un usuario registrado, su ficha usa id = users.id (determinista, creada on-demand en\n-- código), de modo que mascotas/direcciones/pedidos ya existentes (customer_id = user id)\n-- siguen siendo válidos sin migrar datos.\ncreate table if not exists customers (\n  id         uuid primary key default gen_random_uuid(),\n  tenant_id  uuid not null,\n  phone      text,\n  name       text,\n  user_id    uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n-- Un teléfono = un cliente por tenant (evita duplicados). Usuario = una ficha por tenant.\ncreate unique index if not exists customers_by_phone on customers (tenant_id, phone) where phone is not null;\ncreate unique index if not exists customers_by_user on customers (tenant_id, user_id) where user_id is not null;\n\ndo $$\nbegin\n  execute 'alter table customers enable row level security';\n  execute 'alter table customers force row level security';\n  if not exists (select from pg_policies where schemaname = 'public' and tablename = 'customers' and policyname = 'tenant_isolation') then\n    execute 'create policy tenant_isolation on customers using (tenant_id = current_tenant_id()) with check (tenant_id = current_tenant_id())';\n  end if;\nend $$;\n\n-- Pedido: para quién es (mascota, con nombre-snapshot para historial/panel aunque luego se\n-- borre la mascota), forma y estado de pago, y canal de origen.\nalter table orders add column if not exists pet_id         uuid;\nalter table orders add column if not exists pet_name       text;\nalter table orders add column if not exists payment_method text;\nalter table orders add column if not exists payment_status text not null default 'pendiente';\nalter table orders add column if not exists channel        text not null default 'web';\n\ndo $$\nbegin\n  if not exists (select 1 from pg_constraint where conname = 'orders_payment_status_check') then\n    alter table orders add constraint orders_payment_status_check check (payment_status in ('pendiente','pagado'));\n  end if;\n  if not exists (select 1 from pg_constraint where conname = 'orders_channel_check') then\n    alter table orders add constraint orders_channel_check check (channel in ('web','whatsapp','telefono','mostrador'));\n  end if;\nend $$;\n" },
  { name: "0014_zone_eta", sql: "-- Eslabón 3 (zonas de reparto). Tiempo estimado por zona, para mostrarlo al cliente y ordenar\n-- la ruta del cadete. Solo DDL, idempotente. La tarifa por zona ya vive en delivery_rates.\nalter table delivery_zones add column if not exists eta_minutes int;\n" },
  { name: "0015_variant_list_price", sql: "-- Precio anterior / de lista por variante, para mostrar el badge de descuento y el precio\n-- tachado en las cards de \"Ofertas destacadas\". Opcional: si es null o <= precio actual, no\n-- se muestra oferta. Solo DDL, idempotente.\nalter table variants add column if not exists list_price_minor bigint;\n" },
];
